require_once __DIR__ . '/practical_helpers.php'; practicalRequireAdmin(); require __DIR__ . '/db_connect_mysqli.php';
$page=max(1,(int)($_GET['page']??1));$perPage=20;$offset=($page-1)*$perPage;$count=(int)$conn->query('SELECT COUNT(*) c FROM audit_logs')->fetch_assoc()['c'];$logs=$conn->query("SELECT a.*, COALESCE(ad.name, CONCAT('Admin #',a.actor_id)) actor_name FROM audit_logs a LEFT JOIN administrators ad ON ad.id=a.actor_id ORDER BY a.created_at DESC LIMIT $perPage OFFSET $offset")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StudentHub | Audit Logs</title><link rel="stylesheet" href="../css/style.css"></head><body><header class="site-header"><div class="nav-container"><a class="brand" href="../pages/admin_dashboard.php"><img class="brand-logo" src="../images/logo.png" alt="StudentHub"><span class="brand-name">StudentHub</span></a><nav class="main-navigation"><ul class="nav-list"><li><a class="nav-link" href="manage_students.php">Manage Students</a></li><li><a class="nav-link" href="manage_events.php">Manage Events</a></li><li><a class="nav-link active" href="audit_logs.php">Audit Logs</a></li></ul></nav></div></header><main><section><p class="eyebrow">Practical 14</p><h1>Audit Logs</h1><div class="table-container"><table><thead><tr><th>When</th><th>Administrator</th><th>Action</th><th>Entity</th><th>Record ID</th><th>Description</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=htmlspecialchars($log['created_at'])?></td><td><?=htmlspecialchars($log['actor_name'])?></td><td><?=htmlspecialchars($log['action'])?></td><td><?=htmlspecialchars($log['entity_type'])?></td><td><?=htmlspecialchars($log['entity_id'])?></td><td><?=htmlspecialchars($log['description']??'')?></td></tr><?php endforeach?></tbody></table></div><div class="pagination"><?php if($page>1):?><a class="btn-secondary" href="?page=<?=$page-1?>">Previous</a><?php endif?><p>Page <?=$page?> of <?=max(1,ceil($count/$perPage))?></p><?php if($page*$perPage<$count):?><a class="btn-secondary" href="?page=<?=$page+1?>">Next</a><?php endif?></div></section></main></body></html>
